<div class="page-heading"><div><h1>My collection assignments</h1><p class="lead">Tasks assigned to your Cleaner account.</p></div></div>
<form method="get" action="<?= url('schedule/my') ?>" class="filter-panel filter-compact"><label>Status<select name="status"><option value="">All statuses</option><?php foreach (['Assigned','Completed','Skipped'] as $option): ?><option <?= $status === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></label><button class="button button-secondary" type="submit">Apply</button></form>
<div class="table-scroll"><table class="table"><thead><tr><th>Date/time</th><th>Bin/location</th><th>Reason</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($assignments as $assignment): ?><tr><td><?= e($assignment->getSchedule()?->getDate() ?? '') ?><br><?= e($assignment->getSchedule()?->getTimeSlot() ?? '') ?></td><td><?= e($assignment->getBin()?->getBinCode() ?? '') ?><br><small><?= e($assignment->getBin()?->getLocation()?->getFullLabel() ?? '') ?></small></td><td><?= e($assignment->getReason() ?? '') ?></td><td><?= e($assignment->getStatus()) ?></td><td><?php if ($assignment->getStatus() === 'Assigned'): ?><a class="button" href="<?= url('schedule/complete/' . $assignment->getKey()) ?>">Complete</a><?php else: ?><a href="<?= url('schedule/show/' . $assignment->getSchedule()?->getKey()) ?>">View</a><?php endif; ?></td></tr><?php endforeach; ?><?php if ($assignments === []): ?><tr><td colspan="5" class="empty">No assignments match this filter.</td></tr><?php endif; ?></tbody></table></div>
